// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint48 ts1, uint24 back) public {
        uint256 amount = 10 ether;
        vm.assume(ts1 > 1);
        uint256 delta = bound(uint256(back), 1, uint256(ts1) - 1);

        // first call at ts1 succeeds on both versions and sets pastBlockTime = ts1
        vm.warp(ts1);
        (bool ok1, ) = address(c).call{value: amount}("");
        assertTrue(ok1);

        // go back in time: any call at timestamp <= pastBlockTime must revert
        vm.warp(ts1 - delta);
        vm.deal(address(this), amount);
        (bool ok2, ) = address(c).call{value: amount}("");

        // general rule: the time-guard rejects every call at ts <= pastBlockTime
        assertTrue(!ok2, "call at timestamp <= pastBlockTime must revert");
    }
}
